pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        Actor actor = new Actor();
        vm.deal(address(actor), amount);
        actor.doDeposit(c, amount);
        bool ok1 = actor.doWithdraw(c);
        bool ok2 = actor.doWithdraw(c);
        assertTrue(ok1 && ok2 && address(c).balance == 0);
    }
}

contract Actor {
    function doDeposit(ReentrancyDAO c, uint256 amount) external payable {
        c.deposit{value: amount}();
    }
    function doWithdraw(ReentrancyDAO c) external returns (bool) {
        try c.withdrawAll() { return true; } catch { return false; }
    }
    receive() external payable {}
}
